import { parseArgs } from "node:util";
import { TuituiBotClient } from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

function parseTo() {
  const { values } = parseArgs({
    options: {
      account: { type: "string" },
      uid: { type: "string" },
      group: { type: "string" },
    },
  });

  if (values.account && !values.uid && !values.group) {
    return client.to.account(values.account);
  }
  if (values.uid && !values.account && !values.group) {
    return client.to.uid(values.uid);
  }
  if (values.group && !values.account && !values.uid) {
    return client.to.group(values.group);
  }

  console.error(
    "用法: npm run sample:send-mixed -- --account <账号> | --uid <UID> | --group <群ID>",
  );
  process.exit(1);
}

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);
const sampleImage = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";

try {
  const response = await client.im.sendMixed({
    to: parseTo(),
    items: [
      { type: "text", text: "Mixed 消息中的第一段文字" },
      { type: "image", source: sampleImage },
      { type: "text", text: "Mixed 消息中的第二段文字" },
    ],
  });

  console.log("Mixed 消息发送成功", response);
} catch (error) {
  console.error("Mixed 消息发送失败", error);
}
